#include "../internal/sailor_moon_scpu.h"

static int sm_ram_fetch_descriptor(const SmScpuState *cpu, uint32_t address, size_t count, SmStaticFetch *descriptor) {
    if (address != 0x7E0080u || count != 4u) return 0;
    descriptor->guard_address=address; descriptor->guard_count=count;
    descriptor->executable_epoch=1u; descriptor->immutable_byte_mask=9u;
    switch (sm_scpu_context_key(cpu)) {
    case 0x04000400u:
        descriptor->fetch_address=0x800080u;
        descriptor->fetch_count=3u;
        descriptor->deferred_operand_address=0x800081u;
        descriptor->deferred_operand_count=2u;
        return 1;
    case 0x04000418u:
        descriptor->fetch_address=0x800083u;
        descriptor->fetch_count=1u;
        descriptor->deferred_operand_address=0x000000u;
        descriptor->deferred_operand_count=0u;
        return 1;
    case 0x04000402u:
        descriptor->fetch_address=0x800080u;
        descriptor->fetch_count=3u;
        descriptor->deferred_operand_address=0x800081u;
        descriptor->deferred_operand_count=2u;
        return 1;
    case 0x0400041Au:
        descriptor->fetch_address=0x800083u;
        descriptor->fetch_count=1u;
        descriptor->deferred_operand_address=0x000000u;
        descriptor->deferred_operand_count=0u;
        return 1;
    case 0x04100400u:
        descriptor->fetch_address=0x820080u;
        descriptor->fetch_count=3u;
        descriptor->deferred_operand_address=0x820081u;
        descriptor->deferred_operand_count=2u;
        return 1;
    case 0x04100418u:
        descriptor->fetch_address=0x820083u;
        descriptor->fetch_count=1u;
        descriptor->deferred_operand_address=0x000000u;
        descriptor->deferred_operand_count=0u;
        return 1;
    case 0x05400400u:
        descriptor->fetch_address=0xA80080u;
        descriptor->fetch_count=3u;
        descriptor->deferred_operand_address=0xA80081u;
        descriptor->deferred_operand_count=2u;
        return 1;
    case 0x05400418u:
        descriptor->fetch_address=0xA80083u;
        descriptor->fetch_count=1u;
        descriptor->deferred_operand_address=0x000000u;
        descriptor->deferred_operand_count=0u;
        return 1;
    default: return 0;
    }
}

